def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # In the final round, the action cannot affect the opponent's current move,
    # so D weakly dominates C.
    if n >= 99:
        return 'D'

    opp_coops = 0
    for _, o in history:
        if o == 'C':
            opp_coops += 1
    opp_defects = n - opp_coops

    last_me, last_opp = history[-1]

    # If the opponent has never defected yet, probe once and only then decide
    # whether the opponent is truly forgiving or will punish the probe.
    if opp_defects == 0:
        if n < 3:
            return 'C'
        if n == 3:
            return 'D'
        if n == 4:
            return 'C'
        return 'D'

    recent_len = n if n < 8 else 8
    recent_opp_coops = 0
    for _, o in history[-recent_len:]:
        if o == 'C':
            recent_opp_coops += 1

    opp_d_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            opp_d_streak += 1
        else:
            break

    dd_streak = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            dd_streak += 1
        else:
            break

    # Count evidence about how the opponent responds to our defections.
    # forgiven: opponent cooperated in the round after we defected, and was also
    #           cooperating when we exploited them (unilateral defection).
    # punished: opponent defected in the round after we defected.
    forgiven = 0
    punished = 0
    i = 1
    while i < n:
        if history[i - 1][0] == 'D':
            resp = history[i][1]
            if resp == 'D':
                punished += 1
            elif history[i - 1][1] == 'C':
                forgiven += 1
        i += 1

    exploitable = (
        forgiven > 0 and
        punished == 0 and
        opp_coops * 10 >= n * 7 and
        recent_opp_coops * 10 >= recent_len * 5
    )

    if last_opp == 'D':
        if last_me == 'C':
            # Was this defection likely punishment for our previous D?
            caused = n >= 2 and history[-2][0] == 'D'

            if caused:
                # We already returned cooperation; try to restore if the
                # opponent is not simply hostile.
                if opp_coops == 0 or (opp_coops * 10 < n * 3 and opp_d_streak >= 2):
                    return 'D'
                if opp_d_streak <= 2 or recent_opp_coops >= 2:
                    return 'C'
                if opp_coops * 10 >= n * 6 and recent_opp_coops * 10 >= recent_len * 5:
                    return 'C'
                return 'D'

            # Unprovoked D: punish, except extremely cooperative opponents who
            # look like they made a rare slip and whose recent record is clean
            # except for this last D.
            if (
                opp_coops * 10 >= n * 8 and
                opp_d_streak == 1 and
                (recent_len == 1 or recent_opp_coops == recent_len - 1)
            ):
                return 'C'
            return 'D'

        else:
            # Mutual D: try to escape if the opponent has ever cooperated, but
            # do not repeatedly throw away rounds against hostile strategies.
            if opp_coops == 0:
                return 'D'
            if opp_coops * 10 < n * 3 and dd_streak >= 2:
                return 'D'
            if dd_streak <= 1 and recent_opp_coops >= 1 and opp_coops * 10 >= n * 3:
                return 'C'
            if opp_coops * 10 >= n * 6 and recent_opp_coops * 10 >= recent_len * 2:
                return 'C'
            if dd_streak >= 3:
                return 'D'
            if opp_coops >= 2 and recent_opp_coops >= 1:
                return 'C'
            return 'D'

    else:
        # Opponent cooperated last round.
        if exploitable:
            return 'D'

        # If we just defected but have not established exploitability, use one
        # observing cooperative round to see whether the opponent retaliates.
        if last_me == 'D':
            return 'C'

        # Mostly cooperative, and we have no history of the opponent punishing
        # our D, but it is no longer literally all-C. A very conservative probe.
        if (
            punished == 0 and
            forgiven == 0 and
            n >= 15 and
            opp_coops * 10 >= n * 9 and
            recent_opp_coops == recent_len
        ):
            return 'D'

        return 'C'
